<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import type {Analysis} from '../types';
import {time,verdictLabel} from '../types';
import EvidencePanel from './EvidencePanel.vue';
const props=defineProps<{analysis:Analysis}>();
const selected=ref(0),player=ref<HTMLMediaElement|null>(null);
watch(()=>props.analysis.id,()=>selected.value=0);
const active=computed(()=>props.analysis.claims[selected.value]);
function select(i:number){selected.value=i;if(player.value)player.value.currentTime=props.analysis.claims[i].startSeconds;}
const count=(verdict:string)=>props.analysis.claims.filter(c=>c.verdict===verdict).length;
</script>
<template><section class="report"><div class="report-heading"><div><div class="section-label">ANALYSIS REPORT</div><h2>주장별 검증 보고서</h2></div><span class="scope-badge">음성 분석</span></div><p v-if="analysis.demo" class="demo-banner">가상 예시 · 실제 분석 결과가 아닙니다</p><div class="summary-grid"><div><span>검토한 주장</span><strong>{{analysis.claims.length}}<small>개</small></strong></div><div><span>근거로 확인됨</span><strong>{{count('CONFIRMED')}}<small>개</small></strong></div><div><span>반박됨</span><strong>{{count('REFUTED')}}<small>개</small></strong></div><div><span>유보·검토·제외</span><strong>{{analysis.claims.length-count('CONFIRMED')-count('REFUTED')}}<small>개</small></strong></div></div><div class="report-body"><div class="claims-panel"><div v-if="analysis.mediaId" class="media-box"><video ref="player" controls preload="metadata" :src="`/api/media/${analysis.mediaId}`" aria-label="원본 미디어 재생"></video></div><div v-else class="demo-player"><span class="play-circle" aria-hidden="true">▷</span><div><strong>시간 구간으로 주장 살펴보기</strong><p>예시 보고서에는 원본 미디어가 없습니다.</p></div></div><div class="timeline" aria-label="주장 시간 구간"><button v-for="(c,i) in analysis.claims" :key="c.id" @click="select(i)" :class="{selected:selected===i}" :aria-label="`${time(c.startSeconds)} 주장 선택`">{{time(c.startSeconds)}}<span></span></button></div><h3>분석한 주장 <span>{{analysis.claims.length}}</span></h3><button v-for="(c,i) in analysis.claims" :key="c.id" class="claim-card" :class="{selected:selected===i}" :aria-pressed="selected===i" @click="select(i)"><span class="claim-top"><span>{{time(c.startSeconds)}} — {{time(c.endSeconds)}}</span><span class="verdict" :class="c.verdict">{{verdictLabel[c.verdict]}}</span></span><strong>{{c.text}}</strong><span class="claim-bottom">{{c.evidence.length}}개의 근거 <span aria-hidden="true">↗</span></span></button><p v-if="!analysis.claims.length">검증 가능한 주장이 추출되지 않았습니다.</p></div><EvidencePanel v-if="active" :claim="active" :demo="analysis.demo"/></div><div class="limitations"><strong>분석 범위와 한계</strong><ul><li v-for="item in analysis.limitations.filter(s=>!s.startsWith('가상 예시'))" :key="item">{{item}}</li></ul></div></section></template>
